"""Summarize mailbox letters without changing the input tree."""
import argparse
from datetime import datetime, timedelta
import json
from pathlib import Path
import re


RESOLVING = frozenset(("DONE", "BLOCKED", "NEEDS-USER", "FAILED"))
NAME = re.compile(r"^[0-9]{8}T[0-9]{4}[-_]")
MINUTE = timedelta(minutes=1)


def aware_now(value):
    try:
        result = datetime.fromisoformat(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError("--now must be an ISO datetime") from exc
    if result.tzinfo is None:
        raise argparse.ArgumentTypeError("--now must include a timezone")
    return result


def read_letter(path, now):
    try:
        lines = path.read_text(encoding="utf-8").split("\n")
    except (OSError, UnicodeError):
        return None, None, "no_frontmatter"
    if not lines or lines[0] != "---":
        return None, None, "no_frontmatter"
    try:
        end = lines.index("---", 1)
    except ValueError:
        return None, None, "no_frontmatter"
    fields = {}
    for line in lines[1:end]:
        if ": " in line:
            key, value = line.split(": ", 1)
            fields[key] = value
    if any(not fields.get(key) for key in ("id", "from", "to", "status")):
        return None, None, "no_field"
    try:
        at = datetime.fromisoformat(fields.get("at", ""))
    except ValueError:
        return None, None, "no_field"
    if at.tzinfo is None:
        at = at.replace(tzinfo=now.tzinfo)
    try:
        if not NAME.match(path.name):
            raise ValueError("invalid filename")
        datetime.strptime(path.name[:13], "%Y%m%dT%H%M")
    except ValueError:
        return None, None, "bad_name"
    return fields, at, None


def letters(root):
    boxes = {}
    paths = []
    for mailbox in sorted(root.iterdir(), key=lambda path: path.name):
        if mailbox.name.startswith(".") or mailbox.is_symlink() or not mailbox.is_dir():
            continue
        inbox = mailbox / "inbox"
        if inbox.is_symlink() or not inbox.is_dir():
            continue
        boxes[mailbox.name] = {"inbox": {}, "done": 0}
        for folder in (inbox, inbox / "done"):
            if folder.is_symlink() or not folder.is_dir():
                continue
            paths.extend(path for path in folder.iterdir()
                         if not path.name.startswith(".") and path.suffix == ".md"
                         and not path.is_symlink() and path.is_file())
    return boxes, sorted(paths, key=lambda path: path.relative_to(root).as_posix())


def summarize(root, now):
    boxes, paths = letters(root)
    seen = set()
    valid = []
    bad = []
    for path in paths:
        relative = path.relative_to(root).as_posix()
        fields, at, why = read_letter(path, now)
        if why is None and fields["id"] in seen:
            why = "dup_id"
        if why is not None:
            bad.append({"file": relative, "why": why})
            continue
        seen.add(fields["id"])
        valid.append((path, fields, at))
        box = boxes[path.relative_to(root).parts[0]]
        if path.parent.name == "done":
            box["done"] += 1
        else:
            counts = box["inbox"]
            counts[fields["status"]] = counts.get(fields["status"], 0) + 1
    resolved = {fields["re"] for _, fields, _ in valid
                if fields["status"] in RESOLVING and fields.get("re")}
    open_letters = []
    for path, fields, at in valid:
        if fields["status"] != "REQUEST" or fields["id"] in resolved:
            continue
        open_letters.append({"id": fields["id"], "from": fields["from"],
                             "to": fields["to"],
                             "where": "done" if path.parent.name == "done" else "inbox",
                             "age_min": (now - at) // MINUTE})
    open_letters.sort(key=lambda item: (item["to"], item["id"]))
    for box in boxes.values():
        box["inbox"] = dict(sorted(box["inbox"].items()))
    bad.sort(key=lambda item: (item["file"], item["why"]))
    return {"v": 1, "open": open_letters, "boxes": boxes, "bad": bad}


def main(argv=None):
    parser = argparse.ArgumentParser(description="Read-only mailbox todo summary")
    parser.add_argument("folder", type=Path)
    parser.add_argument("--now", required=True, type=aware_now)
    args = parser.parse_args(argv)
    if not args.folder.is_dir():
        parser.error("folder must be a directory")
    try:
        result = summarize(args.folder, args.now)
    except OSError as exc:
        parser.error(str(exc))
    print(json.dumps(result, ensure_ascii=True, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
